[issue_comment] kwikius | created=2016-12-18T19:00:45Z | updated=2016-12-18T19:00:45Z | https://github.com/ArduPilot/ardupilot/pull/5404#issuecomment-267839183
The following appears to work, if you change the comparison to less than or equal and also removes the issues about using other than float. Seems to pss basic tests

```c++
#include <cmath>
#include <type_traits>
#include <limits>
#include <cstdint>

template <class ArithmeticL, class ArithmeticR>
bool is_equal(const ArithmeticL v_1, const ArithmeticR v_2)
{
    static_assert(std::is_arithmetic<ArithmeticL>::value, "template parameter not of type float or int");
    static_assert(std::is_arithmetic<ArithmeticR>::value, "template parameter not of type float or int");
    return std::abs(v_1 - v_2) <= std::numeric_limits<decltype(v_1 - v_2)>::epsilon();
}

#include <iostream>

/*
  do some tests
*/
template <class TL, class TR>
void do_equal(TL const & lhs, TR const & rhs)
{
    if (is_equal(lhs,rhs)){
      std::cout << lhs << " == " << rhs << '\n';
    }else{
      std::cout << lhs << " != " << rhs << '\n';
    }

}

int main()
{
   int v1 = 1;
   long v2 = 2L;

   float v3 = 1.f;
   double v4 = 2.;
   unsigned int v5 = 'X';
   uint8_t  v6 = 'X';

   do_equal(v1,v2);
   do_equal(v1,v3);
   do_equal(v1,v4);
   do_equal(v1,v4);
   do_equal(v1,v5);
   do_equal(v1,v6);

   do_equal(v2,v2);
   do_equal(v2,v3);
   do_equal(v2,v4);
   do_equal(v2,v4);
   do_equal(v2,v5);
   do_equal(v2,v6);

   do_equal(v3,v2);
   do_equal(v3,v3);
   do_equal(v3,v4);
   do_equal(v3,v4);
   do_equal(v3,v5);
   do_equal(v3,v6);

   do_equal(v4,v2);
   do_equal(v4,v4);
   do_equal(v4,v4);
   do_equal(v4,v4);
   do_equal(v4,v5);
   do_equal(v4,v6);

   do_equal(v5,v2);
   do_equal(v5,v5);
   do_equal(v5,v5);
   do_equal(v5,v5);
   do_equal(v5,v5);
   do_equal(v5,v6);

   do_equal(v6,v2);
   do_equal(v6,v6);
   do_equal(v6,v6);
   do_equal(v6,v6);
   do_equal(v6,v5);
   do_equal(v6,v6);
}
```


